+	headHash := head.Hash().String()
+	replicated.CLIVersion = versioninfo.Version
+	replicated.BaseCommit = headHash
+	replicated.RealignAttributionBase(headHash)
+	replicated.WorktreePath = target.WorktreeRoot
+	replicated.WorktreeID = worktreeID
+	replicated.AdoptedIntoWorktreePath = ""
+	replicated.AdoptedIntoWorktreeID = ""
+	replicated.Branch = strategy.GetCurrentBranchName(repo)
+	replicated.LastInteractionTime = &now
+	replicated.Phase = session.PhaseActive
+	replicated.EndedAt = nil
+	replicated.FilesTouched = filesTouched
+
+	// Everything below is repo/checkpoint-local. Carrying any of it from the
+	// source would let the target repo finalize, amend, or attribute against a
+	// checkpoint that only exists in another object store.
+	replicated.StepCount = 0
+	replicated.CheckpointTranscriptStart = 0
+	replicated.CheckpointTranscriptSize = 0
+	replicated.TranscriptIdentifierAtStart = ""
+	replicated.ClearLegacyTranscriptOffsets()
+	replicated.TurnCheckpointIDs = nil
+	replicated.LastCheckpointID = id.EmptyCheckpointID
+	replicated.ClearCondensationAttempt()
+	replicated.LastCheckpointCommitHash = ""
+	replicated.CheckpointTokenUsage = nil
+	replicated.RebaselineSubagentTokens()
+	replicated.FullyCondensed = false
+	replicated.UntrackedFilesAtStart = untrackedFiles
+	replicated.PromptAttributions = nil
+	replicated.PendingPromptAttribution = nil
+	replicated.PromptWindowBase = replicated.SessionTurnCount
+	replicated.PromptWindowResetPending = false
+	replicated.AttachedManually = false
+	replicated.Owner = nil
+	return &replicated, nil
+}
+
+func targetDirtyFiles(ctx context.Context, repo *git.Repository) (touched, untracked []string) {
+	status, err := gitrepo.StatusWithBudget(ctx, repo)
+	if err != nil {
+		return nil, nil
+	}
+	for name, fileStatus := range status {
+		if name == paths.EntireMetadataDir || strings.HasPrefix(name, paths.EntireMetadataDir+"/") {
+			continue
+		}
+		if fileStatus.Worktree == git.Unmodified && fileStatus.Staging == git.Unmodified {
+			continue
+		}
+		touched = append(touched, filepath.ToSlash(name))
+		if fileStatus.Worktree == git.Untracked || fileStatus.Staging == git.Untracked {
+			untracked = append(untracked, filepath.ToSlash(name))
+		}
+	}
+	sort.Strings(touched)
+	sort.Strings(untracked)
+	return touched, untracked
+}
+
+func sameCanonicalPath(a, b string) bool {
+	if a == "" || b == "" {
+		return false
+	}
+	if resolved, err := filepath.EvalSymlinks(a); err == nil {
+		a = resolved
+	}
+	if resolved, err := filepath.EvalSymlinks(b); err == nil {
+		b = resolved
+	}
+	return filepath.Clean(a) == filepath.Clean(b)
+}
