+	if primary {
+		primaryValue = "1"
+	}
+	cmd.Env = append(os.Environ(), bindingReplayEnv+"=1", bindingReplayPrimaryEnv+"="+primaryValue)
+	if err := cmd.Run(); err != nil {
+		return fmt.Errorf("run replayed hook: %w", err)
+	}
+	return nil
+}
